const cfg = $json;
if (!cfg.locationId) throw new Error('Missing locationId');
if (!cfg.apiKey) throw new Error('Missing apiKey in Config node');

const baseUrl = (cfg.apiBaseUrl || 'https://services.leadconnectorhq.com').replace(/\/$/, '');
const locationId = cfg.locationId;
const dryRun = !!cfg.dryRun;

const headers = {
  Authorization: `Bearer ${cfg.apiKey}`,
  Version: '2021-07-28',
  'Content-Type': 'application/json',
  Accept: 'application/json',
};

const keepMap = {
  'UTM Source First': 't5yZ0UGubzs1X0olHyhy',
  'UTM Medium First': 'WulRu4QdE48o2d7gjXNw',
  'UTM Campaign First': 'RKyRrCsg8xsicTUyyH78',
  'UTM Content First': 'zMvJ3fmKxX3ilfq6WotA',
  'UTM Term First': 'X8gW33Z887h3PbjcghW0',
  'UTM Source Last': 'p0X1vD2jDj5AZjXJ6Bcg',
  'UTM Medium Last': 'WsfJa98NxTuXV9lKIL05',
  'UTM Campaign Last': 'IUQRaxhOZQT8tiPZKL1z',
  'UTM Content Last': '9wRews3knMzLhAtqvQog',
  'UTM Term Last': 'dPX3SoyLePXCje9K0ndL',
  'UTM Landing Page First': '2BJCjWu96VkFXlcb2SFP',
  'UTM Landing Page Last': '15oRMShGogK0LnwicFTc',
  'LT Last Routing Reason': 'FQv9wyl2JrMkpf1GPprP',
  'LT Last Routing Channel': 'IPzJpFLekz9TDi4nWBaV',
  'LT Last Routed At': 'aJ3LMhy5fZzh10WoykZ6',
  'LT Route Lock Until': 'o5RwCwvYqAMciL73Dln5',
  'LT Routing Priority': 'ocuVbpOOwczvq00XL7xL',
  'LT Last Event Fingerprint': 'ixsqR8e2HPPvt00S8eYP',
  'LT Last Event At': 'ITv2PYQ75kzKLfOCFhuO',
};

const deleteIds = [
  'rnfxShYEw3a6YxqAP3bq','c1cVpeov2RFpFIeuPhGD','4zvRXRbP4zZIFop8OZg8','FMv1pae7Aqxi5yjRykf3','KkKrZJse6yif8Ro8bKp2',
  'ptELEmY2UVoeR9Qu07ET','pmMe53BRRqPvmfM71Nef','laiwZ6eZF4mUWVJRDFxJ','PExRyRopL9KAZrZnUal5','RYZB1PnfCevO9mA0CppE',
  'plTw2xcJgCV6A4GWrUZp','YZxHpmPwpWvptiyOct62','bimBksRY1gX8y4W1969n','joebUgVFPUgc0m3b0WFV','dytaaVCuJSNsTvJVmFD1',
  '1lEUjdzpfDtjo5S6fRb3','pACgXc5c5NnfbPWkQ2YR','IC1aRN6pMQoQmSC1cu66','aVwe0OfV6G6wdub9wqk5'
];

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (typeof this !== 'undefined' && this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP not available in Code node runtime.');
}

async function apiRequest(method, path, body) {
  const options = { method, url: `${baseUrl}${path}`, headers, json: true };
  if (body !== undefined) options.body = body;
  try {
    const data = await doHttpRequest.call(this, options);
    return { ok: true, status: 200, data };
  } catch (err) {
    const status = err?.statusCode || err?.httpCode || err?.cause?.statusCode || 500;
    const data = err?.response?.body || err?.message || err;
    return { ok: false, status, data };
  }
}

function getCustomFieldsArray(data) {
  if (Array.isArray(data?.customFields)) return data.customFields;
  if (Array.isArray(data?.data?.customFields)) return data.data.customFields;
  if (Array.isArray(data?.data)) return data.data;
  if (Array.isArray(data)) return data;
  return [];
}

const fieldsRes = await apiRequest.call(this, 'GET', `/locations/${locationId}/customFields?model=contact`);
if (!fieldsRes.ok) {
  throw new Error(`Failed to fetch custom fields: ${fieldsRes.status} ${JSON.stringify(fieldsRes.data)}`);
}

const fields = getCustomFieldsArray(fieldsRes.data);
const byId = new Map(fields.map((f) => [f.id, f]));

const validationErrors = [];
for (const [name, keepId] of Object.entries(keepMap)) {
  const f = byId.get(keepId);
  if (!f) {
    validationErrors.push(`KEEP ID NOT FOUND: ${name} -> ${keepId}`);
    continue;
  }
  if ((f.name || '') !== name) {
    validationErrors.push(`KEEP NAME MISMATCH: ${keepId} expected '${name}' got '${f.name || ''}'`);
  }
}

for (const id of deleteIds) {
  if (!byId.has(id)) {
    validationErrors.push(`DELETE ID NOT FOUND: ${id}`);
  }
}

const overlap = deleteIds.filter((id) => Object.values(keepMap).includes(id));
if (overlap.length) {
  validationErrors.push(`SAFETY FAILURE: keep/delete overlap -> ${overlap.join(',')}`);
}

if (validationErrors.length) {
  throw new Error(`VALIDATION_FAILED:\n${validationErrors.join('\n')}`);
}

const results = [];
if (dryRun) {
  for (const id of deleteIds) {
    const f = byId.get(id);
    results.push({ fieldId: id, fieldName: f?.name || '', action: 'Planned Delete (dryRun)' });
  }
} else {
  for (const id of deleteIds) {
    const f = byId.get(id);
    const del = await apiRequest.call(this, 'DELETE', `/locations/${locationId}/customFields/${id}`);
    if (!del.ok) {
      throw new Error(`DELETE_FAILED: ${id} ${JSON.stringify(del.data)}`);
    }
    results.push({ fieldId: id, fieldName: f?.name || '', action: 'Deleted' });
  }
}

return [{
  json: {
    dryRun,
    locationId,
    deletedCount: results.length,
    DELETIONS: results,
    KEPT: Object.entries(keepMap).map(([fieldName, fieldId]) => ({ fieldName, fieldId })),
  }
}];
